            }
            if acknowledged!=block.bytes().len(){return Err(writer.error(SnapshotCauseV1::Attempts,10,interrupted,None));}
            let final_block=block.is_final();
            drop(block);
            writer.progress.block=writer.progress.block.checked_add(1).ok_or_else(||writer.error(SnapshotCauseV1::Arithmetic,11,None,None))?;
            writer.stop(11)?;
            if final_block{break;}
        }
        if writer.progress.bytes!=plan.shape.extent || cursor.emitted_extent()!=plan.shape.extent || writer.progress.block!=plan.shape.blocks{
            return Err(writer.error(SnapshotCauseV1::Shape,12,None,None));
        }
        writer.stop(12)?;
        let observation=SnapshotObservationV1 {bytes:writer.progress.bytes,calls:writer.progress.calls,planning:plan.planning,emission:plan.emission};
        writer.stop(12)?;
        Ok(observation)
    })

(||{
        writer.stop(1)?;
        let view=writer.encode_result(borrow_snapshot_v2(initial),1)?;
        writer.stop(2)?;
        let mut cursor=writer.encode_result(view.into_cursor(),2)?;
        // This checks actual guard data before any metadata/seek/write call.
        let actual=initial.cache.proof().snapshot_counts_v1();
        let mut same=true;
        for i in 0..9 {same &= u64::try_from(actual[i]).ok()==Some(plan.shape.counts[i]);}
        if !same || cursor.encoded_extent()!=plan.shape.extent{return Err(writer.error(SnapshotCauseV1::Shape,3,None,None));}
        writer.stop(4)?;
        let metadata=writer.io_result(output.metadata(),4)?;
        writer.stop(5)?;
        let row_metadata=writer.io_result(rows.metadata(),5)?;
        if !metadata.is_file(){return Err(writer.error(SnapshotCauseV1::NotRegular,6,None,None));}
        if metadata.dev()==row_metadata.dev() && metadata.ino()==row_metadata.ino(){return Err(writer.error(SnapshotCauseV1::Alias,6,None,None));}
        if metadata.len()!=0{return Err(writer.error(SnapshotCauseV1::NotEmpty,6,None,None));}
        writer.stop(7)?;
        let position=writer.io_result(output.stream_position(),7)?;
        if position!=0{return Err(writer.error(SnapshotCauseV1::Position,7,None,None));}
        loop {
            writer.stop(8)?;transfer.fill(0);writer.stop(8)?;
            writer.stop(9)?;
            let block=writer.encode_result(cursor.next_block(transfer),9)?
                .ok_or_else(||writer.error(SnapshotCauseV1::Shape,9,None,None))?;
            if block.offset()!=writer.progress.bytes{return Err(writer.error(SnapshotCauseV1::Shape,9,None,None));}
            let mut acknowledged=0usize;
            let mut interrupted=None;
            for attempt in 1..=32u32 {
                writer.progress.attempt=attempt;
                let requested=&block.bytes()[acknowledged..];
                writer.progress.requested=u64::try_from(requested.len()).map_err(|_|writer.error(SnapshotCauseV1::Arithmetic,10,None,None))?;
                writer.stop(10)?;
                writer.progress.calls=writer.progress.calls.checked_add(1).ok_or_else(||writer.error(SnapshotCauseV1::Arithmetic,10,None,None))?;
                // Exactly one native write per attempt, including Interrupted.
                let returned=output.write(requested);
                let post_stop=initial.control.snapshot_observe_stop_v1().err();
                match returned {
                    Ok(n) if n>0 && n<=requested.len()=>{
                        acknowledged=acknowledged.checked_add(n).ok_or_else(||writer.error(SnapshotCauseV1::Arithmetic,10,None,post_stop))?;
                        writer.progress.bytes=writer.progress.bytes.checked_add(n as u64).ok_or_else(||writer.error(SnapshotCauseV1::Arithmetic,10,None,post_stop))?;
                        // Acknowledged bytes survive cancellation inside write.
                        if let Some(stop)=post_stop{return Err(writer.error(SnapshotCauseV1::Stop(stop),10,None,None));}
                        if acknowledged==block.bytes().len(){break;}
                    },
                    Ok(0)=>return Err(writer.error(SnapshotCauseV1::Zero,10,None,post_stop)),
                    Ok(_)=>return Err(writer.error(SnapshotCauseV1::Overreported,10,None,post_stop)),
                    Err(error) if error.kind()==io::ErrorKind::Interrupted=>{
                        if post_stop.is_some(){return Err(writer.error(SnapshotCauseV1::Io,10,Some(error),post_stop));}
                        interrupted=Some(error);
                    },
                    Err(error)=>return Err(writer.error(SnapshotCauseV1::Io,10,Some(error),post_stop)),
                }
                if attempt==32{return Err(writer.error(SnapshotCauseV1::Attempts,10,interrupted.take(),None));}
            }
            if acknowledged!=block.bytes().len(){return Err(writer.error(SnapshotCauseV1::Attempts,10,interrupted,None));}
            let final_block=block.is_final();
            drop(block);
            writer.progress.block=writer.progress.block.checked_add(1).ok_or_else(||writer.error(SnapshotCauseV1::Arithmetic,11,None,None))?;
            writer.stop(11)?;
            if final_block{break;}
        }
        if writer.progress.bytes!=plan.shape.extent || cursor.emitted_extent()!=plan.shape.extent || writer.progress.block!=plan.shape.blocks{
            return Err(writer.error(SnapshotCauseV1::Shape,12,None,None));
        }
        writer.stop(12)?;
        let observation=SnapshotObservationV1 {bytes:writer.progress.bytes,calls:writer.progress.calls,planning:plan.planning,emission:plan.emission};
        writer.stop(12)?;
        Ok(observation)
    })

fn snapshot_pair_v1(&self,control:&RuntimeControl,wasi:Option<&AccountedWasi>)
        ->Result<(),super::control::SnapshotAdmissionErrorV1>{
        use super::control::SnapshotAdmissionErrorV1 as E;
        control.snapshot_existing_v1()?;
        control.snapshot_owner_v1(self.owner)?;
        control.snapshot_ticket_identity_v1(self.header.as_ref().ok_or(E::Layout)?)?;
        for ticket in &self.buffers {control.snapshot_ticket_identity_v1(ticket.as_ref().ok_or(E::Layout)?)?;}
        control.snapshot_adopted_pair_v1(&self.adopted)?;
        let header=cache_header_bytes().ok_or(E::Arithmetic)?;
        control.snapshot_ticket_v1(self.header.as_ref().ok_or(E::Layout)?,SwiftReservationCategory::Cache,header)?;
        let layouts=[self.slots.capacity().checked_mul(size_of::<SwiftSlot>()),
            self.pins.capacity().checked_mul(size_of::<PinRecord>()),self.patches.capacity().checked_mul(size_of::<decode::Patch>())];
        let mut total=header;
        for (ticket,bytes) in self.buffers.iter().zip(layouts) {
            let bytes=bytes.ok_or(E::Arithmetic)?;
            control.snapshot_ticket_v1(ticket.as_ref().ok_or(E::Layout)?,SwiftReservationCategory::Cache,bytes)?;
            total=total.checked_add(bytes).ok_or(E::Arithmetic)?;
        }
        // Owner is actual cache identity; no imported usage is attributed yet.
        let (wasi_bytes,wasi_tickets)=match wasi {Some(wasi)=>(wasi.snapshot_pair_v1(control)?,5),None=>(0,0)};
        let usage=self.proof().usage();
        control.snapshot_totals_v1(usage.source_bytes,usage.metadata_reserved,total,wasi_bytes,wasi_tickets)?;
        control.snapshot_observe_stop_v1().map_err(E::Stop)
    }

if ticket.owner != self.owner || ticket.category != SwiftReservationCategory::Construction {
            return Err(self.cleanup_fault_with_wasi(
                SwiftCleanupInvariant::ReservationOwner,
                "swift_run_construction_owner",
                wasi,
            ));
        }

if bytes < floor || bytes > ticket.bytes {
            return Err(self.cleanup_fault_with_wasi(
                SwiftCleanupInvariant::ConstructionBound,
                "swift_run_construction_phase_bound",
                wasi,
            ));
        }

if cache.is_some() {
            match super::cache::SwiftFunctionCache::cleanup(&mut cache,&mut control,wasi.as_ref()) {
                Ok(tail)=>tail.complete(cache,&mut cache_retirement),
                Err(failure)=>{cache_retirement=Some(failure);drop(cache);},
            }
        }else{drop(cache);}

pub(super) fn snapshot_totals_v1(&self,source:usize,metadata:usize,cache:usize,wasi:usize,wasi_tickets:usize)->Result<(),SnapshotAdmissionErrorV1>{
        let construction=self.snapshot_foundation_pair_v1()?;
        let shared=size_of::<Self>().checked_add(Cancellation::requested_backing_layout().size()).ok_or(SnapshotAdmissionErrorV1::Arithmetic)?;
        let terms=[(SwiftReservationCategory::RetainedSource,source),(SwiftReservationCategory::RetainedMetadata,metadata),
            (SwiftReservationCategory::Cache,cache),(SwiftReservationCategory::Wasi,wasi),
            (SwiftReservationCategory::Shared,shared),(SwiftReservationCategory::Construction,construction)];
        let mut sum=0usize;
        for (category,bytes) in terms {
            if self.reservations.category(category).current<bytes{return Err(SnapshotAdmissionErrorV1::Layout);}
            sum=sum.checked_add(bytes).ok_or(SnapshotAdmissionErrorV1::Arithmetic)?;
        }
        let tickets=9usize.checked_add(wasi_tickets).ok_or(SnapshotAdmissionErrorV1::Arithmetic)?;
        if self.reservations.combined.current<sum || self.reservations.live_tickets<tickets{return Err(SnapshotAdmissionErrorV1::Layout);}
        Ok(())
    }

pub(super) fn snapshot_storage_preflight_v1(&self,additional:usize)->Result<usize,SnapshotAdmissionErrorV1>{
        let previous=self.snapshot_foundation_pair_v1()?;
        for (current,limit) in [(self.reservations.construction.current,self.category_limit(SwiftReservationCategory::Construction)),
            (self.reservations.combined.current,self.budget.combined_bytes)] {
            current.checked_add(additional).filter(|next|*next<=limit)
                .ok_or(SnapshotAdmissionErrorV1::Storage {current,additional,limit})?;
        }
        self.snapshot_observe_stop_v1().map_err(SnapshotAdmissionErrorV1::Stop)?;
        Ok(previous)
    }

pub(crate) fn snapshot_pair_v1(&self,control:&RuntimeControl)->Result<usize,crate::experimental_swift_reactor::control::SnapshotAdmissionErrorV1>{
        use crate::experimental_swift_reactor::control::SnapshotAdmissionErrorV1 as E;
        use crate::experimental_swift_reactor::control::SwiftReservationCategory as C;
        let header=accounted_header_bytes().ok_or(E::Arithmetic)?;
        control.snapshot_ticket_identity_v1(self.header.as_ref().ok_or(E::Layout)?)?;
        for ticket in &self.buffers {control.snapshot_ticket_identity_v1(ticket.as_ref().ok_or(E::Layout)?)?;}
        control.snapshot_ticket_v1(self.header.as_ref().ok_or(E::Layout)?,C::Wasi,header)?;
        let capacities=[self.context.scratch.capacity(),self.context.rollback.capacity(),self.context.stdout.capacity(),self.context.stderr.capacity()];
        let mut total=header;
        for (ticket,bytes) in self.buffers.iter().zip(capacities) {
            control.snapshot_ticket_v1(ticket.as_ref().ok_or(E::Layout)?,C::Wasi,bytes)?;
            total=total.checked_add(bytes).ok_or(E::Arithmetic)?;
        }
        Ok(total)
    }
